def begin(self, events, time):
    events = bits(events, 5)
    if self.pending is not None or type(time) is not int or time <= self.clock:
        raise ValueError("Pending receipt or nonmonotonic time")
    self.narrow()
    prediction, trace = self.predict(events)
    active = self.schedule()
    if len(active) != UPDATES or len(set(active)) != UPDATES:
        raise AssertionError("Actual update budget violated")
    probabilities = tuple(self.probability(i, events) for i in active)
    self.pending = (time, events, active, probabilities)
    self.clock = time
    return prediction, {**trace, "updated_routes": active}

def run_case(seed, task, condition, historical):
    changed = condition == 'changed'
    samples = rows(seed, task, changed)
    frozen = rows(seed, task, changed, 256, frozen=True)
    true_routes = tuple(ROUTES.index(r) for r in dependencies(seed, task, changed))
    cells = {}
    for history, error in CELLS:
        model = FactorialMemory(seed, history, error)
        stats, snapshots = train(model, samples, true_routes)
        stats['frozen'] = evaluate_cell(model, frozen)
        stats['frozen_replay_equal'] = stats['frozen'] == evaluate_cell(deepcopy(model), frozen)
        stats['final_dependencies_retained'] = all(i in model.pool for i in true_routes)
        stats['initial_new_dependency_absent'] = any(i not in stats['initial_pool'] for i in true_routes)
        if history == 'cumulative' and error == 'public_exponential':
            # Strict JSON equality permits only the registered tuple/list layout binding.
            expected = {k: historical[k] for k in stats}
            canonical = lambda x: json.dumps(x, sort_keys=True, allow_nan=False, separators=(',', ':'))
            if canonical(stats) != canonical(expected):
                raise AssertionError('Historical baseline numerical mismatch')
        cells[history + '__' + error] = {'training': stats, 'snapshots': snapshots,
            'state_sha256': state_digest(model),
            'recovery_within_256': recovery_pass(stats['recovery_ticks'])}
    return {'seed': seed, 'task': task, 'condition': condition, 'cells': cells,
            'historical_baseline_equal': True}

def __init__(self, path, *, publisher_id, scope):
    if not isinstance(path, str) or not path:
        raise AuthoritativeSequenceError("watermark_invalid")
    for value in (publisher_id, scope):
        if not isinstance(value, str) or not 0 < len(value) <= 128 or value != value.strip():
            raise AuthoritativeSequenceError("watermark_invalid")
    try:
        self.path = Path(ensure_parent_directory(path))
        self.lock_path = Path(ensure_allowed_output_path(str(self.path) + ".lock"))
    except (OSError, TypeError, ValueError):
        raise AuthoritativeSequenceError("watermark_invalid") from None
    self.publisher_id = publisher_id
    self.scope = scope
    self._thread_lock = RLock()

def _locked_file(self):
    descriptor = None
    try:
        descriptor = os.open(self.lock_path, os.O_RDWR | os.O_CREAT, 0o600)
        os.chmod(self.lock_path, 0o600)
        if fcntl is not None:
            fcntl.flock(descriptor, fcntl.LOCK_EX)
        else:  # pragma: no cover - Windows only
            if os.fstat(descriptor).st_size == 0:
                os.write(descriptor, b"\0")
                os.fsync(descriptor)
            os.lseek(descriptor, 0, os.SEEK_SET)
            msvcrt.locking(descriptor, msvcrt.LK_LOCK, 1)
        yield
    except AuthoritativeSequenceError:
        raise
    except OSError:
        raise AuthoritativeSequenceError("watermark_unavailable") from None
    finally:
        if descriptor is not None:
            try:
                if fcntl is not None:
                    fcntl.flock(descriptor, fcntl.LOCK_UN)
                else:  # pragma: no cover - Windows only
                    os.lseek(descriptor, 0, os.SEEK_SET)
                    msvcrt.locking(descriptor, msvcrt.LK_UNLCK, 1)
            finally:
                os.close(descriptor)

def load(self):
    with self._thread_lock, self._locked_file():
        return self._read_locked()

def advance(self, sequence):
    if type(sequence) is not int or not 0 <= sequence <= 2**63 - 1:
        raise AuthoritativeSequenceError("watermark_invalid")
    with self._thread_lock, self._locked_file():
        current = self._read_locked()
        if current is not None and sequence <= current:
            raise AuthoritativeSequenceError("publisher_rollback")
        self._write_locked(sequence)
        return sequence
